/**
 * Signals in message CGW_WinCmd.
 *
 * Window hold-to-run command. E2E cyclic, DataID 0x1001. Sent every 20 ms and on a WinCmd_Req change (minimum gap 5 ms)
 *
 * All signal values are as on the CAN bus.
 */
struct locksys_dcu_cgw_win_cmd_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_cmd_crc;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_cmd_alive_ctr;

    /**
     * Requested direction. The DCU moves only while Req is UP or DOWN and every motion permission holds
     *
     * Range: 0..3 (0..3 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_cmd_req;

    /**
     * CGW 8-bit press counter 1..255, wraps and skips 0. 0 = no press. A latched PressId never starts motion
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_cmd_press_id;

    /**
     * Age of the last authenticated APP keep-alive at send time, 10 ms per bit. Raw 255 = no keep-alive or age >= 2550 ms; sent after any non-release stop latch. The DCU rejects motion if the age exceeds 400 ms
     *
     * Range: 0..255 (0..2550 ms)
     * Scale: 10
     * Offset: 0
     */
    uint8_t win_cmd_hold_age;
};

/**
 * Signals in message CGW_DoorCmd.
 *
 * Door lock command. E2E event mode, DataID 0x1002. Sent 3 times at 0, 20 and 40 ms per new ReqId
 *
 * All signal values are as on the CAN bus.
 */
struct locksys_dcu_cgw_door_cmd_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t door_cmd_crc;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t door_cmd_alive_ctr;

    /**
     * Range: 0..3 (0..3 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t door_cmd_req;

    /**
     * CGW 8-bit request counter 1..255, wraps and skips 0. Repetitions of one ReqId cause at most one actuation
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t door_cmd_req_id;
};

/**
 * Signals in message DCU_WinSts.
 *
 * Window status. E2E cyclic, DataID 0x2001. Sent every 50 ms and on change (minimum gap 10 ms)
 *
 * All signal values are as on the CAN bus.
 */
struct locksys_dcu_dcu_win_sts_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_crc;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_alive_ctr;

    /**
     * Range: 0..7 (0..7 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_state;

    /**
     * 0 = fully closed, 100 = fully open, 255 = UNKNOWN. Stage A: always 255. Stage B: derived from encoder counts and the configured travel
     *
     * Range: 0..255 (0..255 %)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_pos_pct;

    /**
     * Reason of the last stop (WindowStopReason). NONE until the first stop after reset
     *
     * Range: 0..31 (0..31 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_stop_reason;

    /**
     * Upper end position active. Reserved in stage A (sent as 0). Stage B: virtual limit, stage D: limit switch
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_lim_up;

    /**
     * Lower end position active. Reserved in stage A (sent as 0). Stage B: virtual limit, stage D: limit switch
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_lim_dn;

    /**
     * Filtered window motor current from the VNH5019 CS output, 0.1 A per bit. Raw 255 = INVALID
     *
     * Range: 0..255 (0..25.5 A)
     * Scale: 0.1
     * Offset: 0
     */
    uint8_t win_sts_current;

    /**
     * Active PressId while moving, otherwise the last latched PressId. After reset: the first PressId received with E2E OK
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_press_id_echo;

    /**
     * Motion not confirmed by the encoder (NO_MOTION) or stall, latched for the press
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_flt_stall;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_flt_over_cur;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_flt_max_run;

    /**
     * End-position plausibility fault. Stage D only (sent as 0 in stages A and B)
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_flt_lim_plaus;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_flt_driver;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_flt_supply;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_flt_comm;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_flt_over_temp;

    /**
     * DCU decision for the PressIdEcho press (CommandResult): UNSPECIFIED = none yet, ACCEPTED = moving, OK = ended by release, other = start rejected or press ended by a non-release stop
     *
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_win_result;

    /**
     * Encoder counts opposite to the commanded direction (DIR_MISMATCH), latched
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_sts_flt_dir_mismatch;
};

/**
 * Signals in message DCU_WinMotion.
 *
 * Window motion telemetry. E2E cyclic, DataID 0x2004. Sent every 50 ms
 *
 * All signal values are as on the CAN bus.
 */
struct locksys_dcu_dcu_win_motion_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_mot_crc;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_mot_alive_ctr;

    /**
     * Encoder supervision verdict (EncoderStatus)
     *
     * Range: 0..7 (0..7 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_mot_enc_sts;

    /**
     * Output-shaft speed averaged over the last 50 ms, 0.1 rpm per bit, positive = UP. Raw -32768 = INVALID
     *
     * Range: -32768..32767 (-3276.8..3276.7 rpm)
     * Scale: 0.1
     * Offset: 0
     */
    int16_t win_mot_speed;

    /**
     * Commanded PWM duty magnitude of the window bridge, 0..100 %
     *
     * Range: 0..100 (0..100 %)
     * Scale: 1
     * Offset: 0
     */
    uint8_t win_mot_duty_pct;

    /**
     * Relative position in encoder counts (x4 decoding) since reset, positive = UP. Low 24 bits of the DCU 32-bit counter, wraps modulo 2^24
     *
     * Range: -8388608..8388607 (-8388608..8388607 counts)
     * Scale: 1
     * Offset: 0
     */
    int32_t win_mot_pos_counts;
};

/**
 * Signals in message DCU_DoorSts.
 *
 * Door lock status. E2E cyclic, DataID 0x2002. Sent every 100 ms and on change (minimum gap 10 ms)
 *
 * All signal values are as on the CAN bus.
 */
struct locksys_dcu_dcu_door_sts_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t door_sts_crc;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t door_sts_alive_ctr;

    /**
     * Derived from the actuator position switch, never from the command
     *
     * Range: 0..7 (0..7 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t door_sts_lock_state;

    /**
     * ReqId of the last accepted door request. Set together with LastResult = ACCEPTED when execution starts
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t door_sts_last_req_id;

    /**
     * Result for LastReqId: ACCEPTED while executing, then OK, FAILED_x or REJECTED_x
     *
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t door_sts_last_result;

    /**
     * Debounced raw level of the lock position switch after polarity calibration (1 = locked position)
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t door_sts_fb_switch;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t door_sts_flt_actuator;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t door_sts_flt_driver;

    /**
     * 1 while 10 actuations lie inside the last 60 s
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t door_sts_rate_limited;

    /**
     * Lock actuation pulses since reset, modulo 256
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t door_sts_act_count;

    /**
     * Peak lock current of the last pulse, 0.1 A per bit
     *
     * Range: 0..255 (0..25.5 A)
     * Scale: 0.1
     * Offset: 0
     */
    uint8_t door_sts_peak_current;
};

/**
 * Signals in message DCU_TempSts.
 *
 * Temperature status. E2E cyclic, DataID 0x2003. Sent every 1000 ms right after each sample
 *
 * All signal values are as on the CAN bus.
 */
struct locksys_dcu_dcu_temp_sts_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t temp_sts_crc;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t temp_sts_alive_ctr;

    /**
     * Range: 0..7 (0..7 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t temp_sts_status;

    /**
     * ECU temperature in 0.01 degC, cdeg = sign(raw)*floor((abs(raw)*78125 + 50000)/100000) from the TMP117 register. Valid -40..125 degC. Raw -32768 = INVALID
     *
     * Range: -32768..32767 (-327.68..327.67 degC)
     * Scale: 0.01
     * Offset: 0
     */
    int16_t temp_sts_value;

    /**
     * Sample counter modulo 256. Equals the UART LSTMP sequence number modulo 256
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t temp_sts_sample_seq;
};

/**
 * Signals in message CGW_NodeSts.
 *
 * CGW heartbeat and status. E2E cyclic, DataID 0x5001. Sent every 100 ms
 *
 * All signal values are as on the CAN bus.
 */
struct locksys_dcu_cgw_node_sts_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t cgw_sts_crc;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t cgw_sts_alive_ctr;

    /**
     * Range: 0..7 (0..7 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t cgw_sts_mode;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t cgw_sts_com_ver_major;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t cgw_sts_com_ver_minor;

    /**
     * Range: 0..3 (0..3 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t cgw_sts_app_link;

    /**
     * Range: 0..7 (0..7 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t cgw_sts_wifi_clients;

    /**
     * Range: 0..7 (0..7 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t cgw_sts_reset_reason;

    /**
     * Number of CGW DTCs with status bit 3 (confirmed) set
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t cgw_sts_dtc_count;

    /**
     * floor(100 * free internal heap / total internal heap), updated every 1 s
     *
     * Range: 0..100 (0..100 %)
     * Scale: 1
     * Offset: 0
     */
    uint8_t cgw_sts_heap_free_pct;
};

/**
 * Signals in message DCU_NodeSts.
 *
 * DCU heartbeat and status. E2E cyclic, DataID 0x5002. Sent every 100 ms from scheduler start (NodeMode INIT reported)
 *
 * All signal values are as on the CAN bus.
 */
struct locksys_dcu_dcu_node_sts_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t dcu_sts_crc;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t dcu_sts_alive_ctr;

    /**
     * Range: 0..7 (0..7 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t dcu_sts_mode;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t dcu_sts_com_ver_major;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t dcu_sts_com_ver_minor;

    /**
     * KL30 voltage, 0.1 V per bit. Raw 255 = INVALID or KL30 sense not fitted
     *
     * Range: 0..255 (0..25.5 V)
     * Scale: 0.1
     * Offset: 0
     */
    uint8_t dcu_sts_vbat;

    /**
     * Range: 0..7 (0..7 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t dcu_sts_reset_reason;

    /**
     * Number of DCU DTCs with status bit 3 (confirmed) set
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t dcu_sts_dtc_count;

    /**
     * Maximum CPU load over 1 s windows since reset
     *
     * Range: 0..100 (0..100 %)
     * Scale: 1
     * Offset: 0
     */
    uint8_t dcu_sts_cpu_load_max;

    /**
     * 1 = window starts inhibited by mode or by an active DTC inhibit
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t dcu_sts_win_inhibit;

    /**
     * 1 = lock actuation inhibited by mode or by an active DTC inhibit
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t dcu_sts_lock_inhibit;
};

